package tools

import (
	"fmt"
	"regexp"
	"strings"
)

// yamlWriter is a minimal writer for the configurations generated by
// convert and discover.
type yamlWriter struct{ b strings.Builder }

func (y *yamlWriter) String() string        { return y.b.String() }
func (y *yamlWriter) blank()                { y.b.WriteString("\n") }
func (y *yamlWriter) comment(s string)      { y.b.WriteString("# " + s + "\n") }
func (y *yamlWriter) key(ind int, k string) { fmt.Fprintf(&y.b, "%s%s:\n", sp(ind), k) }
func (y *yamlWriter) kv(ind int, k, v string) {
	fmt.Fprintf(&y.b, "%s%s: %s\n", sp(ind), k, yq(v))
}
func (y *yamlWriter) item(ind int, k, v string) {
	fmt.Fprintf(&y.b, "%s- %s: %s\n", sp(ind), k, yq(v))
}
func (y *yamlWriter) list(ind int, k string, vs []string) {
	q := make([]string, len(vs))
	for i, v := range vs {
		q[i] = yq(v)
	}
	fmt.Fprintf(&y.b, "%s%s: [%s]\n", sp(ind), k, strings.Join(q, ", "))
}

func sp(n int) string { return strings.Repeat(" ", n) }

var plainOK = regexp.MustCompile(`^[A-Za-z0-9_./@=+-][A-Za-z0-9_./@=+ -]*$`)

// yq quotes a value only when needed.
func yq(s string) string {
	if plainOK.MatchString(s) && !strings.HasSuffix(s, " ") {
		switch strings.ToLower(s) {
		case "true", "false", "yes", "no", "on", "off", "null", "~":
		default:
			return s
		}
	}
	return `"` + strings.NewReplacer(`\`, `\\`, `"`, `\"`).Replace(s) + `"`
}
